INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked, modifier) SELECT 11170, 'BUKTI SURAT PERCERAIAN BERNOMOR (OTOMATIS dari isian #9955#: tiap baris satu butir 1., 2., ...; nomor ketikan dibuang)', 'data_sql', 'SELECT aps_badilag.isian_rtf_bukti((SELECT NULLIF(TRIM(d.data), '''') FROM aps_badilag.abt_data_teks d WHERE d.no_var = 9955 AND d.perkara_id = ''#perkara_id#'' LIMIT 1)) AS data', 0, 'admin' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 11170);
